#include <furi.h>
#include <gui/gui.h>
#include <input/input.h>
#include <furi_hal_usb.h>
#include <furi_hal_usb_hid.h>
#include <furi_hal_random.h>
#include <stdio.h>

/* generated by fbt from .png files in images folder */
#include <keysmash_icons.h>

typedef enum {
    ModeLetters,
    ModeLettersDigits,
    ModeAll,
    ModeCount,
} Mode;

static const char* const mode_names[] = {"A-Z", "A-Z 0-9", "All"};

typedef struct {
    bool running;
    uint32_t keys_sent;
    uint32_t delay_ms;
    bool random_timing;
    Mode mode;
} AppState;

static void draw_cb(Canvas* canvas, void* ctx);
static void input_cb(InputEvent* event, void* ctx);

static uint16_t random_key(Mode mode) {
    uint32_t count = 37;
    if(mode == ModeLetters) {
        count = 26;
    } else if(mode == ModeLettersDigits) {
        count = 36;
    }
    uint32_t r = furi_hal_random_get() % count;
    if(r < 26) {
        return HID_KEYBOARD_A + r;
    } else if(r < 36) {
        return HID_KEYBOARD_1 + (r - 26);
    } else {
        return HID_KEYBOARD_SPACEBAR;
    }
}

int32_t keysmash_app(void* p) {
    UNUSED(p);

    AppState state = {.running = false, .keys_sent = 0, .delay_ms = 50, .random_timing = false, .mode = ModeAll};

    FuriMessageQueue* queue = furi_message_queue_alloc(8, sizeof(InputEvent));

    ViewPort* vp = view_port_alloc();
    view_port_draw_callback_set(vp, draw_cb, &state);
    view_port_input_callback_set(vp, input_cb, queue);

    Gui* gui = furi_record_open(RECORD_GUI);
    gui_add_view_port(gui, vp, GuiLayerFullscreen);

    FuriHalUsbInterface* usb_prev = furi_hal_usb_get_config();
    furi_hal_usb_set_config(&usb_hid, NULL);

    InputEvent event;
    bool alive = true;
    while(alive) {
        uint32_t wait = 50;
        if(state.running) {
            wait = state.delay_ms;
            if(state.random_timing) {
                wait = state.delay_ms / 2 + furi_hal_random_get() % state.delay_ms;
            }
        }
        if(furi_message_queue_get(queue, &event, wait) == FuriStatusOk) {
            if(event.type == InputTypeShort || event.type == InputTypeRepeat) {
                if(event.key == InputKeyBack) {
                    alive = false;
                } else if(event.key == InputKeyOk && event.type == InputTypeShort) {
                    state.running = !state.running;
                    view_port_update(vp);
                } else if(event.key == InputKeyUp) {
                    if(state.delay_ms > 10) {
                        state.delay_ms -= 10;
                    }
                    view_port_update(vp);
                } else if(event.key == InputKeyDown) {
                    if(state.delay_ms < 500) {
                        state.delay_ms += 10;
                    }
                    view_port_update(vp);
                } else if(event.key == InputKeyLeft && event.type == InputTypeShort) {
                    state.random_timing = !state.random_timing;
                    view_port_update(vp);
                } else if(event.key == InputKeyRight && event.type == InputTypeShort) {
                    state.mode = (state.mode + 1) % ModeCount;
                    view_port_update(vp);
                }
            }
        }

        if(state.running) {
            uint16_t key = random_key(state.mode);
            furi_hal_hid_kb_press(key);
            furi_delay_ms(10);
            furi_hal_hid_kb_release(key);
            state.keys_sent++;
            if(state.keys_sent % 20 == 0 || state.delay_ms > 100) {
                view_port_update(vp);
            }
        }
    }

    furi_hal_hid_kb_release_all();
    furi_hal_usb_set_config(usb_prev, NULL);

    gui_remove_view_port(gui, vp);
    view_port_free(vp);
    furi_record_close(RECORD_GUI);
    furi_message_queue_free(queue);

    return 0;
}

static void draw_cb(Canvas* canvas, void* ctx) {
    const AppState* state = ctx;
    char buf[32];
    snprintf(buf, sizeof(buf), "Keys: %lu", (unsigned long)state->keys_sent);

    char delay_buf[32];
    snprintf(
        delay_buf,
        sizeof(delay_buf),
        "Delay: %lu ms%s",
        (unsigned long)state->delay_ms,
        state->random_timing ? " (rand)" : "");

    canvas_clear(canvas);
    canvas_set_font(canvas, FontPrimary);
    canvas_draw_str(canvas, 10, 10, "KeySmash");
    canvas_set_font(canvas, FontSecondary);
    canvas_draw_str_aligned(canvas, 126, 10, AlignRight, AlignBottom, mode_names[state->mode]);
    canvas_draw_str(canvas, 10, 22, state->running ? "Running (OK = stop)" : "Paused (OK = start)");
    canvas_draw_str(canvas, 10, 34, buf);
    canvas_draw_str(canvas, 10, 46, delay_buf);
    canvas_draw_str(canvas, 0, 58, "Spd U/D Rnd L Mode R");
}

static void input_cb(InputEvent* event, void* ctx) {
    FuriMessageQueue* queue = ctx;
    furi_message_queue_put(queue, event, FuriWaitForever);
}


